import { execFileSync } from 'node:child_process'
function query(label,sql){
 if(!/^\s*SELECT\b/i.test(sql)||/;|\b(INSERT|UPDATE|DELETE|REPLACE|ALTER|DROP|CREATE|ATTACH|DETACH|PRAGMA|VACUUM)\b/i.test(sql))throw Error('Non-SELECT rejected '+label)
 const raw=execFileSync('npx',['--no-install','wrangler','d1','execute','orders_db_prod','--config','wrangler.jsonc','--remote','--json','--command',sql],{encoding:'utf8',timeout:120000,maxBuffer:32*1024*1024})
 const r=JSON.parse(raw);if(!Array.isArray(r)||r.some(x=>x.success!==true))throw Error('D1 failed '+label)
 return r.flatMap(x=>x.results||[])
}
const correctionBySource=query('corrections',"SELECT CASE WHEN created_at<'2026-11-01' THEN 'Oct25-31' WHEN created_at<'2026-11-08' THEN 'Nov1-7' WHEN created_at<'2026-11-09' THEN 'Nov8' ELSE 'Nov9-15' END AS period,inventory_source AS source,COUNT(*) AS rows,SUM(CASE WHEN quantity_delta>0 THEN 1 ELSE 0 END) AS positive_rows,SUM(CASE WHEN quantity_delta<0 THEN 1 ELSE 0 END) AS negative_rows,SUM(CASE WHEN quantity_delta=0 THEN 1 ELSE 0 END) AS zero_rows,SUM(CASE WHEN quantity_delta>0 THEN quantity_delta ELSE 0 END) AS positive_units,SUM(CASE WHEN quantity_delta<0 THEN -quantity_delta ELSE 0 END) AS negative_units,MAX(ABS(quantity_delta)) AS largest_single_change,COUNT(DISTINCT COALESCE(reference_id,CAST(id AS TEXT))) AS distinct_references FROM inventory_movements WHERE movement_type='manual_set' AND created_at>='2026-10-25' AND created_at<'2026-11-16' GROUP BY period,inventory_source ORDER BY period,inventory_source")
const checkShortageDays=query('checkShortage',"SELECT substr(checked_at,1,10) AS day,check_type,COUNT(*) AS checks,SUM(CASE WHEN counted_quantity<reserved_quantity THEN 1 ELSE 0 END) AS reserve_above_counted,SUM(CASE WHEN counted_quantity<reserved_quantity THEN reserved_quantity-counted_quantity ELSE 0 END) AS deficit_units_at_check,SUM(CASE WHEN difference_quantity!=0 THEN 1 ELSE 0 END) AS corrected,SUM(ABS(difference_quantity)) AS corrected_abs_units,MAX(ABS(difference_quantity)) AS biggest_correction FROM inventory_stock_checks WHERE checked_at>='2026-10-25' AND checked_at<'2026-11-16' GROUP BY substr(checked_at,1,10),check_type ORDER BY day,check_type")
const evidenceDays=query('operationEvidence',"SELECT substr(occurred_at,1,10) AS day,operation_type,COUNT(*) AS evidence_rows,SUM(CASE WHEN unexplained_quantity>0 THEN 1 ELSE 0 END) AS with_unexplained,SUM(COALESCE(unexplained_quantity,0)) AS unexplained_units,SUM(COALESCE(explained_quantity,0)) AS explained_units,SUM(COALESCE(confirmed_operation_quantity,0)) AS confirmed_operation_units FROM inventory_operation_evidence WHERE occurred_at>='2026-10-25' AND occurred_at<'2026-11-16' GROUP BY substr(occurred_at,1,10),operation_type ORDER BY day,operation_type")
const currentUnresolvedSent=query('sentUnresolved',"SELECT r.id AS reserve_id,r.order_id,r.order_item_id,r.unresolved_reason,r.inventory_source,r.variant_id,r.quantity AS reservation_qty,r.created_at AS reserve_created_at,o.created_at AS order_created_at,o.shipping_status,o.order_status,oi.is_workshop,oi.stock_writeoff_status,oi.quantity AS item_qty,oi.source_type AS item_source,(SELECT COUNT(*) FROM order_dispatch_items di WHERE di.order_item_id=r.order_item_id) AS dispatch_rows FROM inventory_reservations r JOIN orders o ON o.id=r.order_id JOIN order_items oi ON oi.id=r.order_item_id WHERE r.status='unresolved' AND o.shipping_status='sent' ORDER BY r.id LIMIT 20")
const concurrentShortages=query('shortages',"SELECT r.inventory_source,r.variant_id,COUNT(*) AS unresolved_orders, SUM(r.quantity) AS wanted,SUM(COALESCE(s.quantity,0)) AS on_hand_current,SUM(COALESCE(s.reserved_quantity,0)) AS active_reserved_current, MIN(substr(o.created_at,1,10)) AS oldest_order,MAX(substr(o.created_at,1,10)) AS newest_order FROM inventory_reservations r JOIN orders o ON o.id=r.order_id LEFT JOIN inventory_stock s ON s.inventory_source=r.inventory_source AND s.variant_id=r.variant_id WHERE r.status='unresolved' AND r.unresolved_reason='concurrent_shortage' GROUP BY r.inventory_source,r.variant_id ORDER BY unresolved_orders DESC,r.inventory_source")
const skuIdentityPeriod=query('skuPeriod',"SELECT CASE WHEN o.created_at<'2026-11-01' THEN 'Oct25-31' WHEN o.created_at<'2026-11-08' THEN 'Nov1-7' WHEN o.created_at<'2026-11-09' THEN 'Nov8' ELSE 'Nov9-15' END AS period,oi.source_type AS source,COUNT(*) AS lines,SUM(CASE WHEN oi.variant_id IS NULL THEN 1 ELSE 0 END) AS no_sku, SUM(CASE WHEN oi.is_workshop=1 THEN 1 ELSE 0 END) AS workshop_lines FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.created_at>='2026-10-25' AND o.created_at<'2026-11-16' GROUP BY period,oi.source_type ORDER BY period,oi.source_type")
console.log('PICKER_IMPACT_DETAILS_MAIN_READONLY_JSON '+JSON.stringify({correctionBySource,checkShortageDays,evidenceDays,currentUnresolvedSent,concurrentShortages,skuIdentityPeriod}))
